-- 仅改完整命中的旧默认文案；其他非空人工译文保持原值，Token收益业务名称保留。
UPDATE token.translates SET tvalue='进入算力', action_time=UTC_TIMESTAMP(6)
WHERE type=7 AND BINARY tkey=BINARY 'user.ui.products.investToken' AND BINARY lang=BINARY 'zh'
  AND BINARY tvalue=BINARY '投入 Token';
SET @token_tensor_i18n_corrected=@token_tensor_i18n_corrected+ROW_COUNT();
UPDATE token.translates SET tvalue='Open compute', action_time=UTC_TIMESTAMP(6)
WHERE type=7 AND BINARY tkey=BINARY 'user.ui.products.investToken' AND BINARY lang=BINARY 'en'
  AND BINARY tvalue=BINARY 'Allocate Tokens';
SET @token_tensor_i18n_corrected=@token_tensor_i18n_corrected+ROW_COUNT();
UPDATE token.translates SET tvalue='获得 Token 收益返点时，您的算力钱包可用余额须不低于产生收益的下级。', action_time=UTC_TIMESTAMP(6)
WHERE type=7 AND BINARY tkey=BINARY 'user.v21Rewards.vipBalance' AND BINARY lang=BINARY 'zh'
  AND BINARY tvalue=BINARY '获得 Token 收益返点时，您的算力钱包可用 Token 须不低于产生收益的下级。';
SET @token_tensor_i18n_corrected=@token_tensor_i18n_corrected+ROW_COUNT();
UPDATE token.translates SET tvalue='To receive a Token-income rebate, your available compute-wallet balance must be at least the income-generating member''s balance.', action_time=UTC_TIMESTAMP(6)
WHERE type=7 AND BINARY tkey=BINARY 'user.v21Rewards.vipBalance' AND BINARY lang=BINARY 'en'
  AND BINARY tvalue=BINARY 'To receive a Token-income rebate, your available compute-wallet Token must be at least the income-generating member''s balance.';
SET @token_tensor_i18n_corrected=@token_tensor_i18n_corrected+ROW_COUNT();
UPDATE token.translates SET tvalue='当前暂不可执行，请检查可用余额、VIP 状态及次数限制。', action_time=UTC_TIMESTAMP(6)
WHERE type=7 AND BINARY tkey=BINARY 'user.v8.auto.unavailable' AND BINARY lang=BINARY 'zh'
  AND BINARY tvalue=BINARY '当前暂不可执行，请检查可用 Token、VIP 状态及次数限制。';
SET @token_tensor_i18n_corrected=@token_tensor_i18n_corrected+ROW_COUNT();
UPDATE token.translates SET tvalue='Execution is unavailable. Check your available balance, VIP status and execution limits.', action_time=UTC_TIMESTAMP(6)
WHERE type=7 AND BINARY tkey=BINARY 'user.v8.auto.unavailable' AND BINARY lang=BINARY 'en'
  AND BINARY tvalue=BINARY 'Execution is unavailable. Check available Tokens, VIP status and execution limits.';
SET @token_tensor_i18n_corrected=@token_tensor_i18n_corrected+ROW_COUNT();

SET @token_tensor_i18n_changed = @token_tensor_i18n_inserted + @token_tensor_i18n_filled + @token_tensor_i18n_corrected;
UPDATE token.system_setting
SET setting_value = LOWER(UUID()), revision = revision + 1, updated_at = UTC_TIMESTAMP(6)
WHERE BINARY setting_key = BINARY 'i18n.translations.revision' AND @token_tensor_i18n_changed > 0;
SET @token_tensor_i18n_revision_changed = ROW_COUNT();
INSERT INTO token_tensor_i18n_guard (verified)
SELECT 1 WHERE NOT (@token_tensor_i18n_revision_changed = IF(@token_tensor_i18n_changed > 0, 1, 0));
INSERT INTO token_tensor_i18n_guard (verified)
SELECT 1 WHERE NOT ((SELECT revision FROM token.system_setting
  WHERE BINARY setting_key = BINARY 'i18n.translations.revision')
  = @token_tensor_i18n_revision_before + IF(@token_tensor_i18n_changed > 0, 1, 0));
COMMIT;

DROP TEMPORARY TABLE token_tensor_i18n_seed;
DROP TEMPORARY TABLE token_tensor_i18n_guard;
SET SESSION transaction_isolation = @token_tensor_i18n_old_isolation;
SELECT JSON_OBJECT('inserted', @token_tensor_i18n_inserted, 'filled', @token_tensor_i18n_filled,
  'corrected', @token_tensor_i18n_corrected, 'revisionChanged', @token_tensor_i18n_revision_changed) AS token_tensor_i18n_result;
